function acct_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function acct_one(mysqli $db,string $sql):?array{$q=$db->query($sql);return $q?$q->fetch_assoc():null;}
function acct_install(mysqli $db):void{$db->query("CREATE TABLE IF NOT EXISTS player_account_settings (uid INT NOT NULL,theme VARCHAR(32) NOT NULL DEFAULT 'industrial-blue',density ENUM('compact','standard','expanded') NOT NULL DEFAULT 'standard',timezone VARCHAR(64) NOT NULL DEFAULT 'UTC',notify_messages TINYINT(1) NOT NULL DEFAULT 1,notify_battles TINYINT(1) NOT NULL DEFAULT 1,show_online_status TINYINT(1) NOT NULL DEFAULT 1,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS player_security_events (event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,uid INT NOT NULL,event_type ENUM('login','logout','password_change','profile_update','preference_update','failed_login') NOT NULL,ip_address VARCHAR(64) NOT NULL DEFAULT '',details VARCHAR(255) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id),KEY idx_player_security_uid(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("INSERT IGNORE INTO player_account_settings (uid) VALUES ($uid)");}
function acct_event(mysqli $db,int $uid,string $type,string $details=''):void{$ip=$db->real_escape_string((string)($_SERVER['REMOTE_ADDR']??''));$details=$db->real_escape_string($details);$db->query("INSERT INTO player_security_events (uid,event_type,ip_address,details) VALUES ($uid,'$type','$ip','$details')");}
acct_install($db);$message='';$error='';$action=(string)($_GET['id']??'mainDisplay');
$csrf=$_SESSION['account_csrf']??bin2hex(random_bytes(24));$_SESSION['account_csrf']=$csrf;
if($_SERVER['REQUEST_METHOD']==='POST'){$posted=(string)($_POST['csrf']??'');if(!hash_equals($csrf,$posted))$error='Security validation failed. Refresh the account console and try again.';else{$op=(string)($_POST['account_action']??'');if($op==='profile'){$email=trim((string)($_POST['email']??''));$hp=trim((string)($_POST['hpname']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$hp==='')$error='Enter a valid email address and home-world name.';else{$st=$db->prepare('UPDATE users SET email=? WHERE uid=? LIMIT 1');if($st){$st->bind_param('si',$email,$uid);$st->execute();}$st=$db->prepare('UPDATE userdata SET link=? WHERE uid=? LIMIT 1');if($st){$st->bind_param('si',$hp,$uid);$st->execute();}acct_event($db,$uid,'profile_update','Player profile updated');$message='Player profile saved.';}}elseif($op==='preferences'){$density=in_array($_POST['density']??'', ['compact','standard','expanded'],true)?$_POST['density']:'standard';$timezone=trim((string)($_POST['timezone']??'UTC'));$theme='industrial-blue';$messages=isset($_POST['notify_messages'])?1:0;$battles=isset($_POST['notify_battles'])?1:0;$online=isset($_POST['show_online_status'])?1:0;$st=$db->prepare('INSERT INTO player_account_settings (uid,theme,density,timezone,notify_messages,notify_battles,show_online_status) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE density=VALUES(density),timezone=VALUES(timezone),notify_messages=VALUES(notify_messages),notify_battles=VALUES(notify_battles),show_online_status=VALUES(show_online_status)');if($st){$st->bind_param('isssiii',$uid,$theme,$density,$timezone,$messages,$battles,$online);$st->execute();}acct_event($db,$uid,'preference_update','Player preferences updated');$message='Account preferences saved.';}elseif($op==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$user=acct_one($db,"SELECT password FROM users WHERE uid=$uid LIMIT 1");$legacy=(new User())->salt($old);if(!$user||!hash_equals((string)$user['password'],$legacy))$error='Current password is incorrect.';elseif(strlen($new)<8)$error='New passwords must contain at least 8 characters.';elseif($new!==$confirm)$error='New password confirmation does not match.';else{$hash=(new User())->salt($new);$st=$db->prepare('UPDATE users SET password=? WHERE uid=? LIMIT 1');if($st){$st->bind_param('si',$hash,$uid);$st->execute();}$_SESSION['password']=$hash;acct_event($db,$uid,'password_change','Player password changed');$message='Password changed successfully.';}}}}
if($action==='logout'){acct_event($db,$uid,'logout','Player signed out');User::logOut();header('Location: ../index.php');exit;}
$profile=acct_one($db,"SELECT u.uname,u.email,ud.link FROM users u LEFT JOIN userdata ud ON ud.uid=u.uid WHERE u.uid=$uid LIMIT 1")??[];$prefs=acct_one($db,"SELECT * FROM player_account_settings WHERE uid=$uid LIMIT 1")??['density'=>'standard','timezone'=>'UTC','notify_messages'=>1,'notify_battles'=>1,'show_online_status'=>1];$events=$db->query("SELECT event_type,details,created_at FROM player_security_events WHERE uid=$uid ORDER BY event_id DESC LIMIT 12");
?><div class="page-hub account-console"><div class="page-hub-head"><span class="rts-kicker">STARGATE WARS // PLAYER ACCOUNT</span><h3>Player Account and Settings</h3><p>Manage your pilot profile, interface preferences, password security, notifications, and active session.</p></div><?php if($message):?><div class="card rts-alert success"><strong><?=acct_h($message)?></strong></div><?php endif;?><?php if($error):?><div class="card rts-alert danger"><strong><?=acct_h($error)?></strong></div><?php endif;?><div class="rts-unit-grid"><section class="card"><h4>Profile Settings</h4><form class="admin-form-grid" method="post" action="modules/account.php"><input type="hidden" name="csrf" value="<?=acct_h($csrf)?>"><input type="hidden" name="account_action" value="profile"><label>Username<input value="<?=acct_h($profile['uname']??'')?>" disabled></label><label>Email<input type="email" name="email" value="<?=acct_h($profile['email']??'')?>" required></label><label>Home-world name<input name="hpname" value="<?=acct_h($profile['link']??'')?>" required></label><button class="rts-primary">Save Profile</button></form></section><section class="card"><h4>Interface Preferences</h4><form class="admin-form-grid" method="post" action="modules/account.php"><input type="hidden" name="csrf" value="<?=acct_h($csrf)?>"><input type="hidden" name="account_action" value="preferences"><label>Density<select name="density"><option value="compact" <?=($prefs['density']??'')==='compact'?'selected':''?>>Compact</option><option value="standard" <?=($prefs['density']??'')==='standard'?'selected':''?>>Standard</option><option value="expanded" <?=($prefs['density']??'')==='expanded'?'selected':''?>>Expanded</option></select></label><label>Timezone<input name="timezone" value="<?=acct_h($prefs['timezone']??'UTC')?>"></label><label><input type="checkbox" name="notify_messages" <?=!empty($prefs['notify_messages'])?'checked':''?>> Message notifications</label><label><input type="checkbox" name="notify_battles" <?=!empty($prefs['notify_battles'])?'checked':''?>> Battle notifications</label><label><input type="checkbox" name="show_online_status" <?=!empty($prefs['show_online_status'])?'checked':''?>> Show online status</label><button class="rts-primary">Save Preferences</button></form></section></div><section class="card"><h4>Password Security</h4><form class="admin-form-grid" method="post" action="modules/account.php"><input type="hidden" name="csrf" value="<?=acct_h($csrf)?>"><input type="hidden" name="account_action" value="password"><label>Current password<input type="password" name="old_password" required></label><label>New password<input type="password" name="new_password" minlength="8" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required></label><button>Change Password</button></form><p>Passwords are validated through the game’s compatible credential system, and password changes are recorded in the security event history.</p></section><section class="card"><h4>Security Events</h4><table class="mini-table" width="100%"><tr><th>Event</th><th>Details</th><th>Time</th></tr><?php if($events):while($e=$events->fetch_assoc()):?><tr><td><?=acct_h($e['event_type'])?></td><td><?=acct_h($e['details'])?></td><td><?=acct_h($e['created_at'])?></td></tr><?php endwhile;endif;?></table><p><a class="rts-primary" href="javascript:void(0)" onclick="sendData('account','get','logout');return false">Sign out of player account</a></p></section></div><?php $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
